def main():
    parser=argparse.ArgumentParser()
    parser.add_argument("destination", type=Path)
    parser.add_argument("--build", action="store_true")
    parser.add_argument("--run", action="store_true")
    args=parser.parse_args()
    destination=args.destination.resolve()
    if destination.exists() and any(destination.iterdir()):
        parser.error("destination exists and is nonempty: refusal to overwrite")
    destination.mkdir(parents=True, exist_ok=True)
    for name, data in SOURCES.items():
        dst=destination/name
        dst.parent.mkdir(parents=True, exist_ok=True)
        dst.write_text(data, encoding="utf-8", newline="")
        if dst.read_text(encoding="utf-8") != data:
            raise RuntimeError("write verification failed: "+name)
        print("WRITE", dst.relative_to(destination), hashlib.sha256(dst.read_bytes()).hexdigest()[:12])
    print("SELF-SPAWN COMPLETE:", len(SOURCES), "files")
    if args.build or args.run:
        subprocess.run(["cmake","-S",str(destination),"-B",str(destination/"build_workspace_cache"),"-DCMAKE_BUILD_TYPE=Release"],check=True)
        subprocess.run(["cmake","--build",str(destination/"build_workspace_cache"),"-j2"],check=True)
    if args.run:
        target=destination/"build_workspace_cache"/("EntropyAVXEngine.exe" if sys.platform=="win32" else "EntropyAVXEngine")
        subprocess.run([str(target)],check=True)

if __name__=="__main__":
    main()
